from test_nearby import test,setup
P=setup+"local B=BuffTap; B.db.nearbyRequests=true; B.db.nearbyProviderSort=true; B.db.nearbyShowAll=false; local oldClass=UnitClass; UnitClass=function(u) if u=='nameplate1' then return 'Priest','PRIEST' end return oldClass(u) end; aura('nameplate1',5232,'Mark of the Wild'); B:InvalidateAura(); B.nearbyNeedCache={}; B.nearbySnapshot=nil; refresh(); "

test('Provider sorting is opt-in and does not enable requests',"local B=BuffTap; assert(B.db.nearbyProviderSort==false and B.db.nearbyRequests==false)")
test('Sorting admits existing requestable providers without arming casts or whispers',P+"local sent=0; SendChatMessage=function() sent=sent+1 end; local list=B:NearbyPlayers(); assert(#list==1 and list[1].requestProvider and #list[1].actions==0); assert(not B.action and sent==0); assert(B:RequestableBuffs(list[1]))")
test('Disabling requests removes provider-only rows despite saved sort choice',P+"B.db.nearbyRequests=false; assert(#B:NearbyPlayers()==0)")
test('Disabling provider sorting preserves original buffs-only filtering',P+"B.db.nearbyProviderSort=false; assert(#B:NearbyPlayers()==0)")
test('Provider choices use existing request buff selections',P+"for _,def in ipairs(B:CoverageDefinitions()) do B.db.requestBuffs[def.key]=false end; assert(#B:NearbyPlayers()==0)")
test('Already present Priest buffs never become a provider or request',P+"aura('player',1243,'Fortitude'); aura('player',14752,'Divine Spirit'); aura('player',976,'Shadow Protection'); B:InvalidateAura('player'); local entry=B:NearbyPlayers()[1]; assert(not entry); assert(not B:RequestableBuffs({unit='nameplate1',guid=UnitGUID('nameplate1'),class='PRIEST'}))")
test('Receiving buffs before clicking prevents a stale request whisper',P+"local entry=B:NearbyPlayers()[1]; assert(entry); aura('player',1243,'Fortitude'); aura('player',14752,'Divine Spirit'); aura('player',976,'Shadow Protection'); B.events.scripts.OnEvent(nil,'UNIT_AURA','player'); local sent=0; SendChatMessage=function() sent=sent+1 end; assert(not B:RequestBuffFrom(entry) and sent==0)")
test('Missing buff requests remain explicit and keep provider cooldown',P+"local entry=B:NearbyPlayers()[1]; local sent=0; SendChatMessage=function() sent=sent+1 end; assert(B:RequestBuffFrom(entry)); assert(not B:RequestBuffFrom(entry)); assert(sent==1)")
test('Own buff recipients sort ahead of potential providers',P+"C_NamePlate.GetNamePlates=function() return {{GetUnit=function() return 'nameplate1' end},{GetUnit=function() return 'nameplate2' end}} end; B:SeedNearby(); B.nearbyNeedCache={}; B.nearbySnapshot=nil; local list=B:NearbyPlayers(); assert(#list==2 and list[1].unit=='nameplate2' and #list[1].actions>0 and list[2].requestProvider); local display=B:NearbyDisplayList(list); assert(display[1].entry.unit=='nameplate2')")
test('Provider sort control stays in Buff requests and saves independently',"local B=BuffTap; B:Options(); local f=B.helperWindow; local c=f.providerSort; assert(c and c:GetParent()==f.requests); assert(not c:GetChecked()); B.db.nearbyRequests=true; B:UpdateHelperOptions(); c:SetChecked(true); c.scripts.OnClick(c); assert(B.db.nearbyProviderSort and B.db.nearbyRequests)")

test('Existing friend priority remains ahead of an idle provider in both views',P+"C_NamePlate.GetNamePlates=function() return {{GetUnit=function() return 'nameplate1' end},{GetUnit=function() return 'nameplate2' end}} end; aura('nameplate2',5232,'Mark of the Wild'); aura('nameplate2',467,'Thorns'); B.NearbySocialKind=function(_,unit) return unit=='nameplate2' and 'friend' or nil end; B:SeedNearby(); B.db.nearbyShowAll=true; B.nearbyNeedCache={}; B.nearbySnapshot=nil; local list=B:NearbyPlayers(); assert(list[1].unit=='nameplate2' and list[2].requestProvider); B.nearbyDisplay={}; local shown=B:NearbyDisplayList(list); assert(shown[1].entry.unit=='nameplate2')")

test('Provider ordering never reorders rows under the mouse',P+"local first=B:NearbyPlayers(); B.nearbyDisplay={}; B:NearbyDisplayList(first); B.nearbyHovered=true; C_NamePlate.GetNamePlates=function() return {{GetUnit=function() return 'nameplate1' end},{GetUnit=function() return 'nameplate2' end}} end; B:SeedNearby(); B.nearbyNeedCache={}; B.nearbySnapshot=nil; local list=B:NearbyPlayers(); assert(list[1].unit=='nameplate2'); local shown=B:NearbyDisplayList(list); assert(shown[1].entry.unit=='nameplate1'); B.nearbyHovered=false; shown=B:NearbyDisplayList(list); assert(shown[1].entry.unit=='nameplate2')")
